const q = $input.first().json.query || {};
const code = q.code || '';
const state = q.state || '';
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
let body;
if (!code) {
  body = '<h2>⚠️ ไม่พบ code ใน callback</h2><p>การ authorize อาจถูกยกเลิก หรือลิงก์หมดอายุ — ลองเปิดลิงก์ authorize ใหม่อีกครั้ง</p>';
} else {
  body =
    '<h2>✅ ได้รับ code จาก TikTok แล้ว</h2>' +
    '<p>ส่งข้อความด้านล่างนี้ให้ Claude ทันที (code อายุสั้นและใช้ได้ครั้งเดียว)</p>' +
    '<pre id="c">tt_code=' + esc(code) + '\ntt_state=' + esc(state) + '</pre>' +
    '<button onclick="navigator.clipboard.writeText(document.getElementById(\'c\').textContent).then(()=>{this.textContent=\'คัดลอกแล้ว ✓\'})">คัดลอก</button>';
}
const html =
  '<!doctype html><html lang="th"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1"><title>TikTok OAuth Callback</title>' +
  '<style>body{font-family:system-ui,sans-serif;max-width:560px;margin:48px auto;padding:0 16px;color:#222}pre{background:#f4f4f4;padding:12px;border-radius:8px;overflow-x:auto;word-break:break-all;white-space:pre-wrap}button{font-size:16px;padding:8px 20px;border-radius:8px;border:1px solid #888;cursor:pointer}</style>' +
  '</head><body>' + body + '</body></html>';
return [{ json: { html } }];
